def get_curvas(sexo: str, indicador: str) -> dict:
    """
    Retorna dict {percentil: [valor_mes_0, ..., valor_mes_60]}
    sexo: 'M' o 'F'
    indicador: 'peso', 'talla', 'pc'
    """
    s = sexo if sexo in ('M', 'F') else 'M'
    ind = indicador if indicador in ('peso', 'talla', 'pc') else 'peso'
    return OMS[s][ind]


def get_eje_meses(max_meses: int = 60) -> list:
    """Retorna lista de meses de 0 a max_meses."""
    return list(range(0, min(max_meses + 1, 61)))
